(function (window) {
    var jq = window.jQuery = window.jQuery || function () {
        return jq;
    };

    jq.fn = jq.fn || {};

    function chain() {
        return this;
    }

    jq.fn.modal = jq.fn.modal || chain;
    jq.fn.collapse = jq.fn.collapse || chain;
    jq.fn.dropdown = jq.fn.dropdown || chain;
    jq.fn.tab = jq.fn.tab || chain;
})(window);
